 @Test public void licensingOpensAsFourCollapsedGroupsWithoutHorizontalOverflow()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){onView(withContentDescription("App settings")).perform(click());onView(withText("Licensing")).perform(scrollTo(),click());long end=android.os.SystemClock.elapsedRealtime()+20000;boolean[] ready={false};while(android.os.SystemClock.elapsedRealtime()<end){screen.onActivity(a->{try{WebView web=(WebView)value(a,"guideView");ready[0]=web!=null&&"Licensing".equals(web.getTitle())&&web.getContentHeight()>0;}catch(Exception e){throw new AssertionError(e);}});if(ready[0])break;Thread.sleep(100);}assertTrue("Bundled Licensing did not load",ready[0]);screen.onActivity(a->{try{WebView web=(WebView)value(a,"guideView");assertFalse(web.getSettings().getJavaScriptEnabled());assertFalse(web.canScrollHorizontally(1));assertFalse(web.canScrollHorizontally(-1));assertTrue("Licensing initial screen still exposes a huge flat catalog",web.getContentHeight()<1100);}catch(Exception e){throw new AssertionError(e);}});ScreenshotProof.save(c,"licensing-four-groups");}}
 @Test public void activityUsesCompactDatedRowsAndClearsThem()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){screen.onActivity(a->{try{for(String event:new String[]{"Server refreshed","User created","Connection ready"})call(a,"recordActivity",new Class<?>[]{String.class,Gateway.class},event,nodes.get(1));for(Gateway n:(ArrayList<Gateway>)value(a,"gateways"))if(n.get("id").equals(nodes.get(1).get("id")))n.set("protocol","openvpn");call(a,"openScreen",new Class<?>[]{String.class},"Activity");assertTrue(text(a.findViewById(android.R.id.content),"activity-meta").getText().toString().contains("AmneziaWG"));assertEquals(3,count(a.findViewById(android.R.id.content),"activity-row"));assertEquals(1,count(a.findViewById(android.R.id.content),"activity-day"));}catch(Exception e){throw new AssertionError(e);}});onView(withText("Server refreshed")).perform(scrollTo()).check(matches(isDisplayed()));ScreenshotProof.save(c,"activity-dated-list");onView(withText("Clear activity")).perform(scrollTo(),click());onView(withText("Clear activity?")).check(matches(isDisplayed()));onView(withText("Cancel")).perform(click());assertEquals(3,new JSONArray(c.getSharedPreferences("rookstride-ui",0).getString("activityHistory","[]")).length());onView(withText("Clear activity")).perform(scrollTo(),click());ScreenshotProof.save(c,"confirm-clear-activity");onView(withText("Clear")).perform(click());onView(withText("No recent actions.")).check(matches(isDisplayed()));}}
 @Test public void fiveQuickCardsUseDistinctRookArt()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){Set<Integer> images=new HashSet<>();for(int i=0;i<5;i++){final int index=i;screen.onActivity(a->{try{((ViewPager2)value(a,"quickPager")).setCurrentItem(index,false);}catch(Exception e){throw new AssertionError(e);}});InstrumentationRegistry.getInstrumentation().waitForIdleSync();screen.onActivity(a->{try{ViewPager2 pager=(ViewPager2)value(a,"quickPager");View card=pager.findViewWithTag("quick-card-"+QuickConnections.list(nodes,nodes.get(7)).get(index).get("id"));ImageView rook=(ImageView)card.findViewWithTag("quick-rook");android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(80,80,android.graphics.Bitmap.Config.ARGB_8888);android.graphics.drawable.Drawable art=rook.getDrawable().getConstantState().newDrawable().mutate();art.setBounds(0,0,80,80);art.draw(new android.graphics.Canvas(bitmap));int[] pixels=new int[6400];bitmap.getPixels(pixels,0,80,0,0,80,80);images.add(Arrays.hashCode(pixels));bitmap.recycle();assertEquals(index==0?"Recent · Favorite":"Favorite",text(card,"quick-connection-kind").getText().toString());}catch(Exception e){throw new AssertionError(e);}});ScreenshotProof.save(c,"quick-rook-variant-"+i);}assertEquals("Repeated artwork in first five cards",5,images.size());}}
