 @Test public void uninstallAndRemoteRemovalClearFavoritesDurably()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){screen.onActivity(a->{try{ArrayList<Gateway> saved=(ArrayList<Gateway>)value(a,"gateways");Gateway recent=saved.get(7);call(a,"clearRemovedProtocol",new Class<?>[]{Gateway.class},recent);assertFalse(recent.data.optBoolean("favorite"));assertEquals("",c.getSharedPreferences("rookstride-ui",0).getString("lastConnectedId",""));recent.data.put("snapshot",new JSONObject().put("services",new JSONObject()));assertFalse(QuickConnections.list(saved,null).contains(recent));Gateway removed=saved.get(1);JSONObject inventory=new JSONObject().put("installed_protocols",new JSONArray().put("shadowsocks"));call(a,"reconcileServerInventory",new Class<?>[]{Gateway.class,JSONObject.class,JSONObject.class},recent,new JSONObject().put("inventory",inventory),inventory);assertFalse(removed.data.optBoolean("favorite"));assertFalse(removed.data.has("snapshot"));call(a,"save",new Class<?>[]{});}catch(Exception e){throw new AssertionError(e);}});screen.recreate();screen.onActivity(a->{try{ArrayList<Gateway> saved=(ArrayList<Gateway>)value(a,"gateways");assertTrue(QuickConnections.list(saved,null).isEmpty());}catch(Exception e){throw new AssertionError(e);}});}}

