 @Test public void passwordEyeKeepsTextCursorAndMaskingChoice()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){screen.onActivity(a->{try{call(a,"passwordDialog",new Class<?>[]{Gateway.class,Runnable.class},nodes.get(0),(Runnable)()->{throw new AssertionError("No SSH request belongs to this test");});}catch(Exception e){throw new AssertionError(e);}});String label="Server administrator password or key passphrase";onView(withTagValue(is((Object)label))).perform(scrollTo(),click(),replaceText("Sample123"));onView(withTagValue(is((Object)label))).perform(new androidx.test.espresso.ViewAction(){public org.hamcrest.Matcher<View> getConstraints(){return isAssignableFrom(EditText.class);}public String getDescription(){return "wait for password keyboard and dialog layout";}public void perform(androidx.test.espresso.UiController ui,View view){((android.view.inputmethod.InputMethodManager)view.getContext().getSystemService(Context.INPUT_METHOD_SERVICE)).showSoftInput(view,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);long end=android.os.SystemClock.uptimeMillis()+5000;do{ui.loopMainThreadForAtLeast(100);Rect frame=new Rect();view.getWindowVisibleDisplayFrame(frame);if(c.getResources().getDisplayMetrics().heightPixels-frame.bottom>100*c.getResources().getDisplayMetrics().density){ui.loopMainThreadForAtLeast(300);return;}}while(android.os.SystemClock.uptimeMillis()<end);fail("Password keyboard did not become ready");}});onView(withTagValue(is((Object)label))).check((v,error)->{if(error!=null)throw error;EditText e=(EditText)v;assertNotNull(e.getTransformationMethod());assertFalse(e.isSaveEnabled());e.setSelection(4);});onView(withContentDescription("Show "+label.toLowerCase(java.util.Locale.ROOT))).check((v,error)->{if(error!=null)throw error;Rect frame=new Rect(),visible=new Rect();v.getWindowVisibleDisplayFrame(frame);int[] pos=new int[2];v.getLocationOnScreen(pos);View content=v.getRootView().findViewWithTag(RookDialogs.BODY_TAG),top=v.getRootView().findViewById(androidx.appcompat.R.id.topPanel),actions=v.getRootView().findViewById(androidx.appcompat.R.id.buttonPanel);android.util.Log.i("RookEyeBounds","frame="+frame+" eye="+v.getWidth()+"x"+v.getHeight()+" pos="+java.util.Arrays.toString(pos)+" global="+v.getGlobalVisibleRect(visible)+" visible="+visible+" body="+content.getWidth()+"x"+content.getHeight()+" title="+top.getHeight()+" actions="+actions.getHeight());}).perform(scrollTo(),click());onView(withTagValue(is((Object)label))).check((v,error)->{if(error!=null)throw error;EditText e=(EditText)v;assertNull(e.getTransformationMethod());assertEquals("Sample123",e.getText().toString());assertEquals(4,e.getSelectionStart());assertEquals(4,e.getSelectionEnd());});onView(withContentDescription("Hide "+label.toLowerCase(java.util.Locale.ROOT))).perform(click());onView(withTagValue(is((Object)label))).check((v,error)->{if(error!=null)throw error;EditText e=(EditText)v;assertNotNull(e.getTransformationMethod());assertEquals("Sample123",e.getText().toString());assertEquals(4,e.getSelectionStart());assertEquals(4,e.getSelectionEnd());});onView(withText("Cancel")).perform(click());androidx.test.espresso.Espresso.closeSoftKeyboard();}}
 @Test public void accountPasswordUsesTheSameEyeAndPublicProfileUsesAutomaticTrust()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){screen.onActivity(a->{try{Gateway ike=nodes.get(0);ike.data.getJSONObject("snapshot").put("password_policy",new JSONObject().put("advisory",true));call(a,"openVpn",new Class<?>[]{Gateway.class},ike);call(a,"addUser",new Class<?>[]{Gateway.class},ike);}catch(Exception e){throw new AssertionError(e);}});String label="VPN password";onView(withContentDescription("Show "+label.toLowerCase(java.util.Locale.ROOT))).perform(scrollTo(),click());onView(withTagValue(is((Object)label))).check((v,error)->{if(error!=null)throw error;assertNull(((EditText)v).getTransformationMethod());});onView(withContentDescription("Hide "+label.toLowerCase(java.util.Locale.ROOT))).perform(click());onView(withText("Cancel")).perform(click());screen.onActivity(a->{try{Gateway n=nodes.get(0);JSONObject profile=new JSONObject().put("type","ikev2-eap").put("remote",new JSONObject().put("addr","vpn.example.net").put("id","vpn.example.net").put("certreq",false)).put("local",new JSONObject().put("eap_id","fixture-user"));call(a,"installProfile",new Class<?>[]{Gateway.class,JSONObject.class},n,profile);org.strongswan.android.data.VpnProfileDataSource source=new org.strongswan.android.data.VpnProfileSource(a);source.open();try{org.strongswan.android.data.VpnProfile saved=source.getVpnProfile(n.get("profileUuid"));assertNotNull(saved);assertNull("Public certificate profiles must not pin a short-lived leaf",saved.getCertificateAlias());assertEquals("fixture-user",saved.getUsername());source.deleteVpnProfile(saved);}finally{source.close();}}catch(Exception e){throw new AssertionError(e);}});}}

 @Test public void publicAccountSharesReadableLoginDetailsInsteadOfCertificateJson()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){screen.onActivity(a->{try{NewUserShareState state=(NewUserShareState)value(a,"newUserShare");state.created(nodes.get(0).get("id"),"fixture-user","Sample123");state.profile=new JSONObject().put("uuid",java.util.UUID.randomUUID().toString()).put("name","Fixture").put("type","ikev2-eap").put("remote",new JSONObject().put("addr","vpn.example.net").put("id","vpn.example.net")).put("local",new JSONObject().put("eap_id","fixture-user").put("shared_secret","Sample123"));call(a,"restoreCreatedUserShare",new Class<?>[]{});}catch(Exception e){throw new AssertionError(e);}});onView(withText("Share sign-in details")).perform(scrollTo()).check(matches(isCompletelyDisplayed()));ScreenshotProof.save(c,"public-sign-in-sharing");onView(withText("Copy sign-in details")).perform(scrollTo(),click());screen.onActivity(a->{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)c.getSystemService(Context.CLIPBOARD_SERVICE);android.content.ClipData clip=clipboard.getPrimaryClip();assertNotNull(clip);String text=clip.getItemAt(0).getText().toString();assertTrue(text.contains("Server: vpn.example.net\nUsername: fixture-user\nPassword: Sample123"));assertTrue(text.contains("Select automatically"));assertFalse(text.contains("uuid"));assertTrue(clip.getDescription().getExtras().getBoolean("android.content.extra.IS_SENSITIVE"));clipboard.setPrimaryClip(android.content.ClipData.newPlainText("",""));});onView(withText("Done")).perform(click());}}

 @Test public void verifiedPublicMigrationRetainsSavedLoginPasswordAndFavorite()throws Exception{try(ActivityScenario<RookstrideActivity> screen=ActivityScenario.launch(RookstrideActivity.class)){screen.onActivity(a->{org.strongswan.android.data.VpnProfileDataSource source=new org.strongswan.android.data.VpnProfileSource(a);source.open();String id="";try{ArrayList<Gateway> saved=(ArrayList<Gateway>)value(a,"gateways");Gateway n=saved.get(0);String old=String.join("",java.util.Collections.nCopies(64,"1")),next="public-"+String.join("",java.util.Collections.nCopies(32,"2"));org.strongswan.android.data.VpnProfile profile=new org.strongswan.android.data.VpnProfile();profile.setName("Private fixture");profile.setGateway("north.example.net");profile.setVpnType(org.strongswan.android.data.VpnType.IKEV2_EAP);profile.setUsername("fixture-user");profile.setCertificateAlias("old-certificate");source.insertProfile(profile);id=profile.getUUID().toString();n.set("profileUuid",id);n.set("serverInstance",old);n.set("vpnLogin","fixture-user");n.vpnPassword="Sample123";JSONObject health=new JSONObject().put("instance",next).put("certificate",new JSONObject().put("trust","public").put("previous_instance",old).put("aliases",new JSONArray()));JSONObject inventory=new JSONObject().put("installed_protocols",new JSONArray());call(a,"reconcileServerInventory",new Class<?>[]{Gateway.class,JSONObject.class,JSONObject.class},n,new JSONObject().put("gateway",true).put("status",health),inventory);assertEquals(id,n.get("profileUuid"));assertEquals("Sample123",n.vpnPassword);assertEquals("fixture-user",n.get("vpnLogin"));assertTrue(n.data.optBoolean("favorite"));assertEquals(next,n.get("serverInstance"));assertNull(source.getVpnProfile(id).getCertificateAlias());}catch(Exception e){throw new AssertionError(e);}finally{if(!id.isEmpty()){org.strongswan.android.data.VpnProfile profile=source.getVpnProfile(id);if(profile!=null)source.deleteVpnProfile(profile);}source.close();}});}}

